+
+    function evaluateQuestion(fieldset) {
+      const choices = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));
+      const correct = choices.filter((input) => input.dataset.correct === 'true');
+      const selectedCorrect = choices.filter((input) => input.checked && input.dataset.correct === 'true');
+      const selectedIncorrect = choices.filter((input) => input.checked && input.dataset.correct !== 'true');
+
+      return selectedCorrect.length === correct.length && selectedIncorrect.length === 0;
+    }
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      const answered = questions.filter((fieldset) =>
+        fieldset.querySelector('input[type="checkbox"]:checked')
+      ).length;
+      const score = questions.reduce((total, fieldset) => total + (evaluateQuestion(fieldset) ? 1 : 0), 0);
