  <a class="skip-link" href="#quiz">Skip to quiz</a>

  <main id="maincontent">
    <section class="page-shell" aria-labelledby="page-title">
      <header class="hero">
        <p class="eyebrow">Knowledge check</p>
        <h1 id="page-title">Computer Languages Quiz</h1>
        <p>Select every answer that applies. Each question has more than one correct choice.</p>
