      <form id="quiz" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="q1-help">
            <legend>1. Which of these are programming languages?</legend>
            <p id="q1-help" class="help-text">Choose all that are designed for writing software logic.</p>
            <ul class="option-list" role="list">
              <li class="option">
                <label for="q1-a">
                  <input id="q1-a" name="q1" type="checkbox" value="python" data-correct="true">
                  <span>
                    <span class="option-text">Python</span>
                    <span class="option-detail">A general-purpose programming language.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q1-b">
                  <input id="q1-b" name="q1" type="checkbox" value="html" data-correct="false">
                  <span>
                    <span class="option-text">HTML</span>
                    <span class="option-detail">A markup language for structure, not logic.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q1-c">
                  <input id="q1-c" name="q1" type="checkbox" value="javascript" data-correct="true">
                  <span>
                    <span class="option-text">JavaScript</span>
                    <span class="option-detail">Runs in browsers and on servers.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q1-d">
                  <input id="q1-d" name="q1" type="checkbox" value="css" data-correct="false">
                  <span>
                    <span class="option-text">CSS</span>
                    <span class="option-detail">A stylesheet language for presentation.</span>
                  </span>
                </label>
              </li>
            </ul>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which are compiled languages?</legend>
            <ul class="option-list" role="list">
              <li class="option">
                <label for="q2-a">
                  <input id="q2-a" name="q2" type="checkbox" value="c" data-correct="true">
                  <span>
                    <span class="option-text">C</span>
                    <span class="option-detail">Commonly compiled before execution.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q2-b">
                  <input id="q2-b" name="q2" type="checkbox" value="go" data-correct="true">
                  <span>
                    <span class="option-text">Go</span>
                    <span class="option-detail">Typically compiled into a binary.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q2-c">
                  <input id="q2-c" name="q2" type="checkbox" value="ruby" data-correct="false">
                  <span>
                    <span class="option-text">Ruby</span>
                    <span class="option-detail">Usually interpreted or JIT executed.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q2-d">
                  <input id="q2-d" name="q2" type="checkbox" value="rust" data-correct="true">
                  <span>
                    <span class="option-text">Rust</span>
                    <span class="option-detail">Compiled with a strong static type system.</span>
                  </span>
                </label>
              </li>
            </ul>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which are used to define web pages or web page behavior?</legend>
            <ul class="option-list" role="list">
              <li class="option">
                <label for="q3-a">
                  <input id="q3-a" name="q3" type="checkbox" value="html" data-correct="true">
                  <span>
                    <span class="option-text">HTML</span>
                    <span class="option-detail">Describes the page structure and content.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q3-b">
                  <input id="q3-b" name="q3" type="checkbox" value="css" data-correct="true">
                  <span>
                    <span class="option-text">CSS</span>
                    <span class="option-detail">Controls layout, color, and presentation.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q3-c">
                  <input id="q3-c" name="q3" type="checkbox" value="javascript" data-correct="true">
                  <span>
                    <span class="option-text">JavaScript</span>
                    <span class="option-detail">Adds interactivity and behavior.</span>
                  </span>
                </label>
              </li>
              <li class="option">
                <label for="q3-d">
                  <input id="q3-d" name="q3" type="checkbox" value="sql" data-correct="false">
                  <span>
                    <span class="option-text">SQL</span>
                    <span class="option-detail">Used to query databases, not define web pages.</span>
                  </span>
                </label>
              </li>
            </ul>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Check answers</button>
          <p id="quiz-status" class="summary" aria-live="polite">Choose your answers, then check your score.</p>
        </div>

        <div class="answer-key" aria-hidden="true">
          <strong>Answer key:</strong>
          <ul>
            <li>Q1: Python, JavaScript</li>
            <li>Q2: C, Go, Rust</li>
            <li>Q3: HTML, CSS, JavaScript</li>
          </ul>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('quiz');
    const status = document.getElementById('quiz-status');
    const questions = Array.from(form.querySelectorAll('.form-field fieldset'));

    function evaluateQuestion(fieldset) {
      const choices = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));
      const correct = choices.filter((input) => input.dataset.correct === 'true');
      const selectedCorrect = choices.filter((input) => input.checked && input.dataset.correct === 'true');
      const selectedIncorrect = choices.filter((input) => input.checked && input.dataset.correct !== 'true');

      return selectedCorrect.length === correct.length && selectedIncorrect.length === 0;
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const answered = questions.filter((fieldset) =>
        fieldset.querySelector('input[type="checkbox"]:checked')
      ).length;
      const score = questions.reduce((total, fieldset) => total + (evaluateQuestion(fieldset) ? 1 : 0), 0);

      status.textContent = `You answered ${score} out of ${questions.length} questions correctly${answered < questions.length ? '. Try selecting answers for every question.' : '.'}`;
    });
  </script>
