472.       const selectedCorrect = choices.filter((input) => input.checked && input.dataset.correct === 'true');
473.       const selectedIncorrect = choices.filter((input) => input.checked && input.dataset.correct !== 'true');
474. 
475.       return selectedCorrect.length === correct.length && selectedIncorrect.length === 0;
476.     }
